def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opponents += 1
            if opp.get('budget', 0) >= budget:
                rich_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    if hp <= 2 or no_water_days >= 2:
        bid = max(0.92 * DAILY_SALARY, highest_prev + 2.5)
        return float(min(budget, bid))

    if hp <= 4 or no_water_days >= 1:
        if tight_supply:
            bid = max(0.82 * DAILY_SALARY, highest_prev + 1.5)
        else:
            bid = max(0.68 * DAILY_SALARY, min(highest_prev * 0.9, highest_prev - 3.0 if highest_prev > 0 else 48.0))
        return float(min(budget, bid))

    base = 0.34 * DAILY_SALARY
    if tight_supply:
        base = 0.48 * DAILY_SALARY
    elif loose_supply:
        base = 0.24 * DAILY_SALARY

    if highest_prev >= 0.85 * DAILY_SALARY:
        bid = base
    elif highest_prev > 0:
        bid = max(base, min(0.62 * DAILY_SALARY, avg_prev * 0.55))
    else:
        bid = base

    if urgent_opponents >= 2 and hp >= 5:
        bid *= 0.85
    if rich_opponents >= 2 and tight_supply and hp <= 5:
        bid = max(bid, 0.58 * DAILY_SALARY)

    if day >= 8 and hp >= 6 and budget < 250:
        bid *= 0.8

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Read yesterday traces for immediate reaction
    prev_bids = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Base aggressiveness from yesterday's market pressure
    # If others were bidding close to daily salary, we must bid enough to secure water.
    # But since we don't know exact allocation rules, keep bid in a mid band to avoid waste.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # High pressure yesterday
        if my_hp <= 2.0:
            target = DAILY_SALARY * 0.95
        elif my_hp <= 4.0:
            target = DAILY_SALARY * 0.75
        else:
            target = DAILY_SALARY * 0.65
    else:
        # Moderate pressure
        if my_hp <= 2.0:
            target = DAILY_SALARY * 0.85
        elif my_hp <= 4.0:
            target = DAILY_SALARY * 0.65
        else:
            target = DAILY_SALARY * 0.55

    # Supply-aware slight adjustment: when supply is higher, we can bid slightly less.
    # supply range is 15..25 (meta scenario medium)
    # Normalize: 15->0, 25->1
    norm = (supply - 15.0) / 10.0
    if norm < 0.0:
        norm = 0.0
    if norm > 1.0:
        norm = 1.0

    # If supply is scarce, increase bid; if abundant, decrease bid.
    target = target * (1.08 - 0.12 * norm)

    # No-water days: if we've been without water, increase urgency.
    no_water_days = float(my_status.get('no_water_days', 0.0))
    if no_water_days >= 2.0:
        target *= 1.15
    elif no_water_days >= 1.0:
        target *= 1.07

    # Budget cap
    bid = min(my_budget, target)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_yesterday_bid = max(yesterday_bids) if yesterday_bids else 0.0

    bid = 0.0
    day_factor = day_context['day'] / EPISODE_DAYS # Scales from 0.1 to 1.0 over the episode

    if my_status['hp'] <= 2: # Critical HP
        bid = DAILY_SALARY * (0.95 + day_factor * 0.05) # Very aggressive, increases with day
    elif my_status['hp'] <= 5: # Low HP
        if max_yesterday_bid > 0:
            bid = max(max_yesterday_bid * 1.05, DAILY_SALARY * 0.8) * (1 + day_factor * 0.05)
        else:
            bid = DAILY_SALARY * (0.8 + day_factor * 0.05)
    elif my_status['hp'] <= 8: # Medium HP
        if max_yesterday_bid > 0:
            bid = max(max_yesterday_bid * 1.02, DAILY_SALARY * 0.65) * (1 + day_factor * 0.02)
        else:
            bid = DAILY_SALARY * (0.65 + day_factor * 0.02)
    else: # High HP
        if max_yesterday_bid > 0:
            bid = max(max_yesterday_bid * 0.98, DAILY_SALARY * 0.55) * (1 + day_factor * 0.01) # Slightly above or below, conservative
        else:
            bid = DAILY_SALARY * (0.55 + day_factor * 0.01)

    bid = max(0.0, bid)
    bid = min(my_status['budget'], bid)

    # If budget is critically low and HP is also critical, bid everything to survive
    if my_status['hp'] <= 2 and my_status['budget'] < DAILY_SALARY * 0.5:
        bid = my_status['budget']

    return bid

